package com.vibeguard.samples.audit; import java.time.Instant; import java.util.List; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Provides staff-only access to a bounded, read-only audit event list. */ @RestController @RequestMapping("/internal/audit-events") public class AuditController { @Value("${AUDIT_STAFF_KEY:}") private String staffKey; private final List<Event> events=List.of(new Event("account.created","user-001",Instant.parse("2026-01-01T00:00:00Z")),new Event("profile.updated","user-001",Instant.parse("2026-01-02T00:00:00Z"))); @GetMapping public ResponseEntity<List<Event>> list(@RequestHeader("X-Audit-Staff-Key") String key){return !staffKey.isBlank()&&staffKey.equals(key)?ResponseEntity.ok(events):ResponseEntity.status(401).build();}record Event(String action,String subject,Instant occurredAt){} }
